ALTER TABLE public.products ADD COLUMN category text NOT NULL DEFAULT 'General', ADD COLUMN active boolean NOT NULL DEFAULT true;
CREATE OR REPLACE FUNCTION public.validate_sales_document() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE subtotal numeric:=0; item jsonb; parent public.sales_documents; BEGIN
IF jsonb_typeof(NEW.items) IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.items)=0 OR jsonb_array_length(NEW.items)>100 THEN RAISE EXCEPTION 'Add between 1 and 100 line items'; END IF;
FOR item IN SELECT * FROM jsonb_array_elements(NEW.items) LOOP IF item->>'name' IS NULL OR length(trim(item->>'name'))=0 OR item->>'quantity' IS NULL OR item->>'price' IS NULL OR (item->>'quantity')::numeric<=0 OR (item->>'quantity')::numeric>1000000 OR (item->>'price')::numeric<0 OR (item->>'price')::numeric>999999999999 THEN RAISE EXCEPTION 'Invalid line item'; END IF; subtotal:=subtotal+round((item->>'quantity')::numeric*(item->>'price')::numeric,2); END LOOP;
IF NEW.total IS DISTINCT FROM subtotal THEN RAISE EXCEPTION 'Document total must match its line items'; END IF;
IF NEW.parent_id IS NOT NULL THEN SELECT * INTO parent FROM public.sales_documents WHERE id=NEW.parent_id; IF parent.id IS NULL OR parent.owner_id<>NEW.owner_id OR parent.organization_id<>NEW.organization_id OR parent.lead_id<>NEW.lead_id OR parent.status<>'Issued' OR NOT ((NEW.kind='Order' AND parent.kind='Quotation') OR (NEW.kind='Invoice' AND parent.kind='Order')) THEN RAISE EXCEPTION 'Invalid document link'; END IF; END IF;
IF TG_OP='UPDATE' THEN IF NEW.items IS DISTINCT FROM OLD.items OR NEW.total<>OLD.total OR NEW.kind<>OLD.kind OR NEW.parent_id IS DISTINCT FROM OLD.parent_id OR NEW.lead_id<>OLD.lead_id OR NEW.owner_id<>OLD.owner_id OR NEW.organization_id<>OLD.organization_id THEN RAISE EXCEPTION 'Document financial details are immutable'; END IF; IF NEW.status='Cancelled' AND (EXISTS(SELECT 1 FROM public.payments WHERE invoice_id=OLD.id) OR EXISTS(SELECT 1 FROM public.sales_documents WHERE parent_id=OLD.id AND status<>'Cancelled')) THEN RAISE EXCEPTION 'Cannot cancel a paid or linked document'; END IF; END IF;
RETURN NEW; END $$;